def _kat_liste(metin):
    """'MONİTÖR · KASA' → ['MONİTÖR','KASA'] (BÜYÜK, boşlar atılır)."""
    return [_tr_upper(x.strip()) for x in str(metin or "").split("·") if x.strip()]

degisiklikler.yeni:
def _kat_bosluksuz(s):
    """Karşılaştırma anahtarı: BÜYÜK harf + tüm boşluklar atılmış.
    'Mouse Pad' · 'MOUSEPAD' · 'mouse  pad' → hepsi 'MOUSEPAD'."""
    return "".join(_tr_upper(s).split())


def kategori_kanonik(ad):
    """Serbest yazılmış kategori adını KATALOG yazımına çevirir.

    SORUN: ref kaydına 'MOUSEPAD', ürün kartına 'Mouse Pad' yazılıyordu.
    İkisi ayrı anahtar üretiyor; Kâr/P&L kategori filtresi katalog adını
    arayınca desteği bulamıyor, destek ayrı bir satır olarak kalıyordu.

    YÖNTEM: elle alias listesi TUTULMAZ — katalogla (KATEGORI_LISTE)
    boşluksuz karşılaştırılır. Katalog büyüdükçe eşleme kendiliğinden
    büyür, ikinci bir liste bakımı gerekmez. (depo_kanonik ile aynı fikir.)

    BELİRSİZ ADLAR ÇEVRİLMEZ: 'SOĞUTUCU' katalogdaki 'CPU Soğutucu',
    'Kule Soğutucu', 'Sıvı Soğutma'dan hangisi olduğu bilinemez. Tahmin
    etmek desteği yanlış kategoriye yazar; olduğu gibi bırakılır ve
    raporda kendi adıyla görünür.
    """
    ham = _tr_upper(str(ad or "").strip())
    if not ham:
        return ""
    anahtar = _kat_bosluksuz(ham)
    if not anahtar:
        return ""
    try:
        from .database import KATEGORI_LISTE
    except Exception:
        return ham
    for kat in KATEGORI_LISTE:
        if _kat_bosluksuz(kat) == anahtar:
            return _tr_upper(kat)
    return ham


def _kat_liste(metin):
    """'MONİTÖR · KASA' → ['MONİTÖR','KASA'] (BÜYÜK, boşlar atılır).
    Kategori adları katalog yazımına çevrilir (bkz. kategori_kanonik)."""
    return [kategori_kanonik(x) for x in str(metin or "").split("·")
            if str(x).strip() and kategori_kanonik(x)]
